  "grammar.v2.adjectives.na": "Grupo な",
  "grammar.v2.adjectives.i": "Grupo い",
  "grammar.v2.adjectives.naNow": "な · no pasado",
  "grammar.v2.adjectives.naPast": "な · pasado",
  "grammar.v2.adjectives.iNow": "い · no pasado",
