  "grammar.n5.practice.memory": "Results for this round, without saving progress",
  "grammar.n5.practice.tip.eyebrow": "KEY IDEA",
  "grammar.n5.practice.tip.title": "Read before choosing",
  "grammar.n5.practice.tip.body": "Check what the instructions ask, what the sentence means and how its parts connect.",
  "grammar.n5.practice.result": "PRACTICE RESULTS",
